CREATE TABLE IF NOT EXISTS public.roles(code text PRIMARY KEY,name_ar text NOT NULL,description text NOT NULL DEFAULT '',is_system boolean NOT NULL DEFAULT false,is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),retired_by uuid,retired_reason text);
GRANT SELECT ON public.roles TO authenticated;GRANT ALL ON public.roles TO service_role;ALTER TABLE public.roles ENABLE ROW LEVEL SECURITY;
CREATE TABLE IF NOT EXISTS public.capabilities(code text PRIMARY KEY,name_ar text NOT NULL,category text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());GRANT SELECT ON public.capabilities TO authenticated;GRANT ALL ON public.capabilities TO service_role;ALTER TABLE public.capabilities ENABLE ROW LEVEL SECURITY;
CREATE TABLE IF NOT EXISTS public.role_permissions(role text NOT NULL REFERENCES public.roles(code),capability text NOT NULL REFERENCES public.capabilities(code),level text NOT NULL DEFAULT 'none' CHECK(level IN('none','view','own','edit','approve')),updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid,PRIMARY KEY(role,capability));GRANT SELECT ON public.role_permissions TO authenticated;GRANT ALL ON public.role_permissions TO service_role;ALTER TABLE public.role_permissions ENABLE ROW LEVEL SECURITY;
CREATE TABLE IF NOT EXISTS public.user_role_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,role text NOT NULL REFERENCES public.roles(code),is_active boolean NOT NULL DEFAULT true,assigned_at timestamptz NOT NULL DEFAULT now(),assigned_by uuid,reason text,UNIQUE(user_id,role));GRANT SELECT ON public.user_role_assignments TO authenticated;GRANT ALL ON public.user_role_assignments TO service_role;ALTER TABLE public.user_role_assignments ENABLE ROW LEVEL SECURITY;
CREATE TABLE IF NOT EXISTS public.staff_accounts(user_id uuid PRIMARY KEY,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','inactive')),deactivated_at timestamptz,deactivated_by uuid,reason text,auth_sync_status text NOT NULL DEFAULT 'not_required',updated_at timestamptz NOT NULL DEFAULT now());GRANT SELECT ON public.staff_accounts TO authenticated;GRANT ALL ON public.staff_accounts TO service_role;ALTER TABLE public.staff_accounts ENABLE ROW LEVEL SECURITY;
INSERT INTO public.roles(code,name_ar,is_system) SELECT enumlabel,CASE enumlabel WHEN 'admin' THEN 'أدمن' WHEN 'manager' THEN 'مدير — عرض فقط' WHEN 'leasing_manager' THEN 'مدير التأجير' WHEN 'sales_agent' THEN 'وسيط مبيعات' WHEN 'accountant' THEN 'محاسب' WHEN 'control' THEN 'كنترول' WHEN 'investor' THEN 'مستثمر — متوافق' WHEN 'tenant' THEN 'مستأجر' ELSE 'مستخدم' END,true FROM pg_enum WHERE enumtypid='public.app_role'::regtype ON CONFLICT DO NOTHING;
INSERT INTO public.user_role_assignments(user_id,role,is_active,reason) SELECT user_id,role::text,is_active,'نقل تعيين قائم إلى سجل الصلاحيات' FROM public.user_roles ON CONFLICT(user_id,role) DO NOTHING;
CREATE OR REPLACE FUNCTION public.permission_levels_allow(_granted text,_requested text) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$ SELECT CASE _requested WHEN 'view' THEN _granted IN('view','edit','approve') WHEN 'own' THEN _granted IN('own','edit','approve') WHEN 'edit' THEN _granted='edit' WHEN 'approve' THEN _granted='approve' ELSE false END $$;
CREATE OR REPLACE FUNCTION public.has_permission(_capability text,_level text DEFAULT 'view') RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.staff_accounts s WHERE s.user_id=auth.uid() AND s.status='inactive') AND EXISTS(SELECT 1 FROM public.user_role_assignments a JOIN public.roles r ON r.code=a.role AND r.is_active JOIN public.role_permissions p ON p.role=r.code WHERE a.user_id=auth.uid() AND a.is_active AND p.capability=_capability AND public.permission_levels_allow(p.level,_level)) $$;
REVOKE ALL ON FUNCTION public.has_permission(text,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.has_permission(text,text) TO authenticated,service_role;
CREATE POLICY roles_read ON public.roles FOR SELECT TO authenticated USING(true);CREATE POLICY capabilities_read ON public.capabilities FOR SELECT TO authenticated USING(true);CREATE POLICY matrix_read ON public.role_permissions FOR SELECT TO authenticated USING(true);CREATE POLICY assignments_read ON public.user_role_assignments FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));CREATE POLICY staff_read ON public.staff_accounts FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.sync_legacy_role_assignment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.user_role_assignments(user_id,role,is_active,reason) VALUES(NEW.user_id,NEW.role::text,NEW.is_active,'توافق تعيين الدور') ON CONFLICT(user_id,role) DO UPDATE SET is_active=excluded.is_active;RETURN NEW;END $$;
CREATE TRIGGER legacy_role_permission_sync AFTER INSERT OR UPDATE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.sync_legacy_role_assignment();REVOKE ALL ON FUNCTION public.sync_legacy_role_assignment() FROM PUBLIC,anon,authenticated;
ALTER TABLE public.assignment_state ENABLE ROW LEVEL SECURITY;REVOKE ALL ON public.assignment_state FROM anon,authenticated;GRANT ALL ON public.assignment_state TO service_role;
ALTER TABLE public.party_code_counter ENABLE ROW LEVEL SECURITY;REVOKE ALL ON public.party_code_counter FROM anon,authenticated;GRANT ALL ON public.party_code_counter TO service_role;
SELECT to_regclass('public.role_permissions') IS NOT NULL AS matrix_ready,(SELECT count(*) FROM public.user_role_assignments) AS preserved_assignments;